import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { missionsAPI } from '../services/api';

const MissionsPage = () => {
  const { balance } = useAuth();
  const [missions, setMissions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMissions = async () => {
      try {
        const missionsResponse = await missionsAPI.getMissions();
        setMissions(missionsResponse.data);
      } catch (error) {
        console.error('Error fetching missions:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchMissions();
  }, []);

  const handleCheckProgress = async (missionId, type) => {
    try {
      let response;
      if (type === 'case_opening') {
        response = await missionsAPI.checkCaseOpening();
      } else if (type === 'upgrade') {
        response = await missionsAPI.checkUpgrade();
      }

      // In a real app, we'd update the mission progress based on response
      alert('Mission progress checked!');
      // Refresh missions data
      const missionsResponse = await missionsAPI.getMissions();
      setMissions(missionsResponse.data);
    } catch (error) {
      console.error('Error checking mission progress:', error);
      alert('Error checking mission progress: ' + (error.response?.data?.detail || error.message || 'Request failed'));
    }
  };

  if (loading) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <h1 className="mb-4 gradient-text">Missions</h1>
      <div className="alert alert-info">
        Virtual currency — no real-money value
      </div>
      <div className="row mb-4">
        <div className="col-md-8">
          <h2>Balance: <span className="text-success">{balance.toLocaleString()} €</span></h2>
        </div>
      </div>

      {/* Missions Grid */}
      <div className="row g-4">
        {missions.length > 0 ? (
          missions.map(mission => (
            <div key={mission.id} className="col-md-4">
              <div className="card hover-lift">
                <div className="card-body">
                  <h5 className="card-title">{mission.title}</h5>
                  <p className="card-text">{mission.description}</p>
                  <div className="d-flex justify-content-between align-items-center mb-3">
                    <span className="badge bg-info">{mission.current_progress}/{mission.target_progress}</span>
                    <span className="fs-6">{Math.round((mission.current_progress / mission.target_progress) * 100)}%</span>
                  </div>
                  <div className="progress" style={{ height: '10px' }}>
                    <div className="progress-bar bg-gradient" 
                         role="progressbar" 
                         style={{ width: `${(mission.current_progress / mission.target_progress) * 100}%` }}></div>
                  </div>
                  {!mission.is_completed && mission.current_progress < mission.target_progress ? (
                    <button className="btn btn-outline-primary w-100 btn-sm" 
                            onClick={() => handleCheckProgress(mission.id, mission.type)}>
                      Check Progress
                    </button>
                  ) : mission.is_completed ? (
                    <button className="btn btn-success w-100 btn-sm" disabled>
                      Claimed
                    </button>
                  ) : (
                    <button className="btn btn-primary w-100 btn-sm" 
                            onClick={() => handleCheckProgress(mission.id, mission.type)}>
                      Complete Mission
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="col-12">
            <div className="text-center py-5">
              <h3>No missions available</h3>
              <p className="text-muted">Check back later for new challenges!</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default MissionsPage;
